# 주문 데이터 처리
from functools import reduce
from typing import List, Dict

# 순수 함수들
def calculate_item_total(item: Dict) -> Dict:
    return {**item, 'total': item['price'] * item['quantity']}

def apply_discount(item: Dict, discount_rate: float) -> Dict:
    discounted_price = item['price'] * (1 - discount_rate)
    return {**item, 'price': discounted_price}

def calculate_tax(item: Dict, tax_rate: float) -> Dict:
    tax_amount = item['total'] * tax_rate
    return {**item, 'tax': tax_amount, 'total_with_tax': item['total'] + tax_amount}

# 함수 합성으로 주문 처리
def process_order(items: List[Dict], discount_rate: float = 0.0, tax_rate: float = 0.1):
    return list(map(
        lambda item: calculate_tax(
            calculate_item_total(
                apply_discount(item, discount_rate)
            ), tax_rate
        ),
        items
    ))

# 사용 예시
order_items = [
