def transform_user_data(raw_user: Dict) -> Dict:
    return {
        'id': raw_user['user_id'],
        'name': f"{raw_user['first_name']} {raw_user['last_name']}",
        'email': raw_user['email_address'].lower(),
        'is_premium': raw_user['subscription_type'] == 'premium'
    }

def filter_active_users(users: List[Dict]) -> List[Dict]:
    return list(filter(lambda user: user.get('status') == 'active', users))

def sort_by_registration_date(users: List[Dict]) -> List[Dict]:
    return sorted(users, key=lambda user: user['registration_date'], reverse=True)

# 함수 합성
def process_user_list(raw_users: List[Dict]) -> List[Dict]:
    return sort_by_registration_date(
        list(map(transform_user_data, filter_active_users(raw_users)))
    )
